 assert [(c['site'],c['target']) for c in f['calls']]==[('06C9:5AE8','06C9:5B5A'),('06C9:5AF6','06C9:5B5A'),('06C9:5B07','06C9:5C30'),('06C9:5B19','06C9:5C30'),('06C9:5B39','06C9:5C30'),('06C9:5B4B','06C9:5C30')]
 callers=[{'owner':v['entry'],**c} for v in g['functions'] for c in v['calls'] if c['target']=='06C9:5ADA'];assert len(callers)==1 and callers[0]['site']=='06C9:1B44';owner=next(v for v in g['functions'] if v['entry']=='06C9:1B2C');window=[view(ip) for ip in sorted(owner['instructions']) if 0x1b2c<=ip<=0x1b5a]
 record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'instruction_observations':observations,'actual_near_callees':f['calls'],'direct_caller_candidates':callers,'caller_instruction_window':window,'flow_ledger':graph,'flow_ledger_sha256':hashlib.sha256((ROOT/graph).read_bytes()).hexdigest(),'facts':['NoSSarguments/PUSHSI/PUSHDI/PUSHBP; two actual near5B5A calls set BP39A3/3813 and pass raw origin330E/330C/end5356/5354. Explicit child DS overrides retain intended record segment.','Two unconditional5C30 calls use AX/DXfrom52C8/52CA and raw counts; selected SI minus record base stores330E/330C. Nonzero byte3379 enables two additional calls with AX/DXfrom52D0/52D2 and stores3312/3310. Child-clobbered BP is retained until actual parentPOPBP.','Counts are reread at each sourceMOV, not cached or validated.5C30 shiftsCXright3 then do-onceLOOP, so count0 entails65536 comparisons; original upper/ring validity notinvented.','All six nearCALL frames are actual SS writes and real childRET2. Parent actualPOPBP/DI/SI/plainfarRETF consumes4. Changed childret CS/IP/SP exposesrawstate after actualRET before following any target.','RootSP24 ensures childSP16 after three saved words and near frame, meeting frozen child minimum. Parentcall and perchildloop budgets expose distinct sites/prefixstate. Single1B2C:1B44 farcaller recorded; enclosing state body/writers/lifetime/core stillopen.'],'limits':'Static sequence/caller window plus actual-child composition, not whole state-machine/caller/writer/capacity/sortedness/lifetime/exclusion/otherFLAGS/core/resource-fedP2/P3/device/session/gameplay/fidelity acceptance.'};out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','root_sites':41,'actual_near_sites':6,'direct_callers':1}))
